const policy = $json[0] || { requires_approval: false, default_timeout_min: 30, escalation_timeout_min: 15 };
const context = JSON.parse($json.context || '{}');

let needsApproval = policy.requires_approval;

// Evaluate condition_json if present
if (policy.condition_json && Object.keys(policy.condition_json).length > 0) {
  const condition = policy.condition_json;

  if (condition.recipients_gt && context.recipients > condition.recipients_gt) {
    needsApproval = true;
  } else if (condition.rows_gt && context.rows > condition.rows_gt) {
    needsApproval = true;
  } else if (condition.amount_usd_gt && context.amount_usd > condition.amount_usd_gt) {
    needsApproval = true;
  } else if (condition.writes && context.writes === true) {
    needsApproval = true;
  } else if (condition.critical && context.critical === true) {
    needsApproval = true;
  } else {
    needsApproval = false;
  }
}

return [{
  json: {
    needs_approval: needsApproval,
    action_type: $json.action_type,
    risk_level: $json.risk_level,
    policy: policy,
    context: context,
    timeout_minutes: needsApproval ? policy.default_timeout_min : 0,
    escalation_timeout_min: needsApproval ? policy.escalation_timeout_min : 0
  }
}];
